import json
import subprocess
import os

def main(match_id):

    # RUN Match Preprocess for MAtch ID
    subprocess.run(["python", "-m", "stats.match_analyzer", str(match_id)], check=True)


    # TAke the off_diff.json and add it to aws

    off_set_path = f"outputs/{match_id}/offset_diff.json"

    subprocess.run(["aws", "s3", "cp", off_set_path, f"s3://pitch-control-calc/outputs/{match_id}/offset_diff.json", "--profile", "pitch-control"], check=True)

    # Delete the output folder

    subprocess.run(["rm", "-rf", f"outputs/{match_id}"], check=True)




